"""Original Endocrine chapter one: diagnosis and diabetes classification."""
from qbank_authoring import question,ref,finalize
DX=ref('ADA Standards of Care in Diabetes—2026: Diagnosis and Classification','https://doi.org/10.2337/dc26-s002')
T1=ref('ADA/EASD Updated Consensus: Management of Type 1 Diabetes in Adults, 2026','https://diabetesjournals.org/care/article-pdf/doi/10.2337/dci26-0122/894606/dci260122.pdf')
MO=ref('Endotext: Diagnosis and Clinical Management of Monogenic Diabetes','https://www.ncbi.nlm.nih.gov/sites/books/NBK563964/')
rows=[]
def q(*a,**k):rows.append(question(*a,**k))
q('An asymptomatic adult has laboratory A1C 6.7% and fasting plasma glucose 119 mg/dL. Repeat A1C using a standardized method is 6.6%, with no condition altering A1C reliability. What is the correct classification?', 'Diabetes mellitus',[
 ('Prediabetes because fasting glucose is below 126 mg/dL','Two valid A1C results at or above 6.5% establish diabetes even when fasting glucose is below its threshold.'),('Normal glycemia because both tests must exceed their thresholds','Concordant abnormal results from different modalities are not mandatory.'),('Unconfirmed diabetes until an OGTT is performed','A third diagnostic method is not required after the valid repeated abnormal test.')],
 'Confirm the abnormal diagnostic test when results are discordant', '**Two A1C values at or above 6.5% satisfy the diagnostic criterion when the assay is appropriate.**',['Different tests identify partly overlapping populations.','Marked persistent discordance should prompt review for interference or altered biology.'], '**Do not average a diagnostic result down with a different test.**',['Assess symptoms and the full metabolic context.','Start classification and management after confirmation.'],[['A1C criterion','At least 6.5%'],['Asymptomatic confirmation','Two abnormal results'],['Discordance','Repeat the above-threshold test']],[DX],'clinical_scenario')
q('Polyuria, polydipsia and unexplained weight loss accompany a random plasma glucose of 265 mg/dL. Which diagnostic statement is correct?', 'Classic symptoms plus random plasma glucose at least 200 mg/dL establish diabetes without routine repeat confirmation',[
 ('A fasting test is mandatory before diabetes can be diagnosed','The symptomatic random-glucose criterion is sufficient.'),('The result indicates only impaired glucose tolerance','The value and symptoms meet a diabetes criterion.'),('An A1C below 6.5% would always negate the diagnosis','Rapid-onset diabetes can have a less elevated A1C.')],
 'Unequivocal symptomatic hyperglycemia is a special diagnostic pathway', '**Classic symptoms with random plasma glucose at least 200 mg/dL meet the criterion.**',['A hyperglycemic crisis also establishes clear disease.','Evaluate for insulin deficiency and ketosis when indicated.'], '**Do not delay necessary treatment for confirmatory testing.**',['Determine likely type and urgency.','A1C can still help estimate prior glycemic exposure.'],[['Symptoms','Polyuria/polydipsia/weight loss'],['Random glucose','At least 200 mg/dL'],['Repeat requirement','Not routine in this unequivocal setting']],[DX],'clinical_scenario')
q('Which fasting plasma glucose result meets the ADA impaired fasting glucose range in a nonpregnant adult?', '112 mg/dL',[
 ('95 mg/dL','This is below the ADA impaired fasting range.'),('128 mg/dL','This is in the diabetes range and requires appropriate confirmation if asymptomatic.'),('145 mg/dL','This is above the diabetes threshold, not merely impaired fasting glucose.')],
 'Specify the diagnostic framework and pregnancy context', '**ADA defines impaired fasting glucose as 100–125 mg/dL.**',['The diabetes fasting threshold is at least 126 mg/dL.','Fasting means no caloric intake for at least eight hours.'], '**Use the risk state to support prevention.**',['Prediabetes is associated with elevated future diabetes and cardiovascular risk.','Different organizations and pregnancy protocols can use different cutoffs.'],[['ADA impaired fasting','100–125 mg/dL'],['Diabetes fasting','At least 126 mg/dL'],['Preparation','At least eight-hour fast']],[DX])
q('After a standard 75-g oral glucose load, a nonpregnant adult has two-hour plasma glucose 172 mg/dL. Which category is correct?', 'Impaired glucose tolerance',[
 ('Normal glucose tolerance','The two-hour value exceeds 139 mg/dL.'),('Diabetes by the two-hour criterion','The diabetes threshold is at least 200 mg/dL.'),('Gestational diabetes by this nonpregnant test alone','Pregnancy-specific criteria do not apply to this patient.')],
 'The two-hour OGTT evaluates a different glycemic dimension', '**Impaired glucose tolerance spans 140–199 mg/dL.**',['A two-hour result at or above 200 mg/dL meets a diabetes criterion.','The fasting value can be less abnormal than the postload value.'], '**Ensure appropriate preparation and interpretation.**',['Acute illness and major dietary restriction can affect results.','Offer structured risk reduction and follow-up.'],[['Normal two-hour','Below 140 mg/dL'],['IGT','140–199 mg/dL'],['Diabetes','At least 200 mg/dL']],[DX])
q('A patient recently received a major blood transfusion. Which method is preferred for diagnosing suspected diabetes during the period when A1C is unreliable?', 'Plasma glucose criteria',[
 ('A1C interpreted without regard to transfusion','Donor erythrocytes and changed red-cell populations can distort A1C.'),('Urine glucose alone','The renal threshold varies and this is not a diagnostic criterion.'),('A single sensor glucose estimate as an established replacement for diagnostic plasma testing','CGM is not the standard diagnostic criterion in this setting.')],
 'A1C depends on erythrocyte biology as well as glucose', '**Transfusion, altered red-cell survival and some hemoglobin variants can disrupt interpretation.**',['Hemolysis can lower A1C relative to glycemia.','Some variants interfere in an assay-specific way.'], '**Use fasting, postload or symptomatic random plasma glucose as appropriate.**',['Investigate a large A1C-glucose discrepancy.','Alternative glycated proteins may help monitoring in selected cases but have their own limitations.'],[['A1C confounder','Changed red-cell population'],['Diagnostic alternative','Plasma glucose'],['Monitoring alternatives','Selected context dependent']],[DX],'clinical_scenario')
q('Which situation can cause an A1C lower than expected for the actual average glucose?', 'Increased red-cell turnover from hemolysis',[
 ('Prolonged red-cell survival as the sole mechanism','Longer exposure tends to increase glycation, the opposite direction.'),('A completely normal erythrocyte lifespan with a valid assay','This lacks the specified confounder.'),('Recent sustained glucose lowering with old highly glycated cells still present','This can keep A1C relatively high while current glucose improves.')],
 'Glycation accumulates over red-cell exposure time', '**Shortened erythrocyte survival reduces time available for glycation.**',['A1C can therefore underestimate glycemia.','The cause must be distinguished from assay interference.'], '**Compare with measured glucose and clinical history.**',['Use a suitable monitoring method when the relationship is altered.','Avoid intensifying or withholding treatment from A1C alone in a confounded setting.'],[['Shorter survival','Potential falsely low A1C'],['Recent change','A1C lags current glucose'],['Action','Check glucose and biological context']],[DX])
q('An adult with obesity develops weight loss, ketosis and rapid failure of noninsulin therapy. What is the best classification principle?', 'Evaluate autoimmune insulin deficiency despite the adult age and obesity',[
 ('Obesity rules out type 1 diabetes','Insulin resistance and autoimmune diabetes can coexist.'),('All diabetes diagnosed after age 30 is type 2','Adult-onset autoimmune diabetes is common enough to require recognition.'),('Ketosis permanently proves one subtype without further assessment','Ketosis-prone type 2 and other forms also exist.')],
 'Phenotype alone can misclassify adult diabetes', '**Unexpected insulin deficiency warrants islet-antibody and appropriate C-peptide assessment.**',['Do not delay insulin when clinically needed.','Body habitus is informative but not definitive.'], '**Reassess classification as the course becomes clearer.**',['GAD is commonly the first antibody tested.','Additional IA-2 or ZnT8 testing can reduce false-negative classification.'],[['Suggestive course','Weight loss/ketosis/rapid failure'],['Testing','Autoantibodies and C-peptide'],['Treatment urgency','Do not delay necessary insulin']],[DX,T1],'clinical_scenario')
q('A lean 46-year-old initially controlled without insulin has GAD antibodies and progressive loss of insulin secretion. Which description is most appropriate?', 'Adult-onset autoimmune diabetes with a slowly progressive course',[
 ('Type 2 diabetes is proven by the initial insulin-free period','An initial insulin-free interval does not exclude autoimmune disease.'),('GCK-MODY as the best fit for progressive autoimmune loss','GCK disease usually causes stable mild hyperglycemia without islet autoimmunity.'),('Pancreatogenic diabetes established by GAD positivity','GAD supports autoimmune disease rather than pancreatic destruction from another cause.')],
 'The term LADA describes a clinical course within autoimmune diabetes', '**Islet autoimmunity can progress more slowly in adults.**',['Insulin need can develop over time.','A single low-titer antibody result should still be interpreted in its clinical and assay context.'], '**Anticipate progressive insulin deficiency.**',['Educate about ketosis and sick-day management when relevant.','Avoid assuming noninsulin treatment can substitute indefinitely for absent insulin.'],[['Autoimmunity','GAD or other islet antibodies'],['Course','May initially be insulin independent'],['Later need','Insulin as secretion declines']],[DX,T1],'clinical_scenario')
q('What is the main clinical value of C-peptide when diabetes type is uncertain?', 'Estimating endogenous insulin secretion',[
 ('Directly measuring injected insulin dose','Exogenous insulin does not contain C-peptide.'),('Identifying the specific islet autoantibody','Antibody assays are separate tests.'),('Proving type 2 diabetes from any detectable result','Residual secretion can persist in autoimmune disease.')],
 'C-peptide is released with endogenous insulin', '**Interpret it with concurrent glucose, timing and renal function.**',['Hypoglycemia suppresses secretion.','Kidney impairment can increase circulating C-peptide by reducing clearance.'], '**Use the value to answer a defined classification question.**',['Do not assess residual secretion during or immediately after a hyperglycemic emergency without considering transient suppression.','An apparently reassuring value must not delay treatment of clinical insulin deficiency.'],[['Source','Endogenous beta cells'],['Confounders','Glucose and kidney function'],['Limitation','Not a stand-alone subtype label']],[DX,T1])
q('A 23-year-old has diabetes across three successive generations, negative islet antibodies and persistent endogenous insulin secretion years after diagnosis. Which next step is most appropriate?', 'Consider monogenic diabetes and arrange targeted genetic evaluation when the phenotype supports it',[
 ('Assume all young-onset diabetes is autoimmune','The family pattern and preserved secretion raise another possibility.'),('Diagnose one specific MODY gene solely from age','Genetic and phenotype evaluation are needed.'),('Stop all treatment before confirming the mechanism','Treatment decisions should remain safe while evaluation proceeds.')],
 'A vertical inheritance pattern can identify a treatable molecular subtype', '**Autosomal dominant monogenic diabetes often appears in successive generations.**',['Obesity does not completely exclude a monogenic cause.','Negative antibodies and preserved C-peptide strengthen suspicion in context.'], '**Choose testing that fits the clinical phenotype.**',['A molecular diagnosis can change therapy and family counseling.','Do not equate every familial type 2 cluster with MODY.'],[['Clues','Early onset and vertical inheritance'],['Support','Preserved secretion/negative antibodies'],['Confirmation','Appropriate genetic testing']],[DX,MO],'clinical_scenario')
q('A nonpregnant adult has lifelong stable fasting glucose around 115–140 mg/dL, a small postload increment and a pathogenic GCK variant. Which approach is usually appropriate?', 'Observation without routine glucose-lowering medication, with pregnancy managed separately',[
 ('Immediate lifelong high-dose insulin for every affected adult','Stable GCK-MODY commonly does not require medication outside pregnancy.'),('Sulfonylurea treatment because all MODY subtypes respond identically','Gene-specific mechanisms and treatment differ.'),('Ignore pregnancy implications because the variant is benign in every setting','Fetal genotype and growth can affect pregnancy management.')],
 'GCK changes the glucose set point', '**Glucokinase-related diabetes usually produces mild stable hyperglycemia.**',['Microvascular complications are uncommon in the typical phenotype.','Progressive or marked hyperglycemia suggests another coexisting process.'], '**Avoid unnecessary treatment while preserving appropriate follow-up.**',['Provide genetic counseling.','Use specialist pregnancy assessment rather than copying the nonpregnant rule.'],[['Mechanism','Raised glucose-sensing threshold'],['Typical course','Stable mild hyperglycemia'],['Treatment','Usually none outside pregnancy']],[DX,MO],'clinical_scenario')
q('A pathogenic HNF1A variant confirms monogenic diabetes in a patient with preserved insulin secretion. Which treatment sensitivity is characteristic?', 'Marked sensitivity to low-dose sulfonylureas in suitable patients',[
 ('Universal absence of response to any insulin secretagogue','HNF1A disease is often responsive.'),('Routine absence of any treatment need throughout life like typical GCK-MODY','HNF1A disease is generally progressive.'),('Sulfonylureas have no hypoglycemia risk in this subtype','Sensitivity makes careful low-dose use important.')],
 'Molecular classification can change the preferred therapy', '**HNF1A-related beta-cell dysfunction can respond strongly to sulfonylureas.**',['The course and complication risk differ from GCK disease.','Some patients eventually need additional therapy or insulin.'], '**Make any transition under supervision.**',['Avoid abruptly stopping insulin in an uncertain diagnosis.','Monitor for hypoglycemia and reassess control over time.'],[['HNF1A','Often sulfonylurea sensitive'],['GCK','Usually stable and untreated'],['Safety','Low-dose individualized initiation']],[DX,MO])
q('Diabetes is diagnosed at four months of age. What is the key classification step?', 'Urgent evaluation for neonatal monogenic diabetes',[
 ('Assume ordinary autoimmune type 1 diabetes without considering genetics','Diabetes before six months is rarely typical autoimmune disease.'),('Wait until adulthood for molecular testing','The diagnosis can immediately alter treatment.'),('Exclude diabetes because infants cannot develop it','Persistent infant hyperglycemia needs prompt assessment.')],
 'Age at onset can be a powerful genetic clue', '**Diagnosis before six months warrants molecular investigation.**',['KCNJ11 and ABCC8 channel variants are among important causes.','Some channel-related cases can transition from insulin to high-dose sulfonylureas under specialist care.'], '**Treat hyperglycemia safely while testing proceeds.**',['The gene determines whether a treatment change is appropriate.','Assess syndromic features and family counseling needs.'],[['Age','Before six months'],['Priority','Molecular diagnosis'],['Potential benefit','Gene-directed treatment']],[DX,MO],'clinical_scenario')
q('Diabetes is accompanied by renal cysts, congenital urinary tract abnormalities and hypomagnesemia. Which monogenic cause is particularly suggestive?', 'HNF1B-related disease',[
 ('GCK-MODY','It usually causes isolated stable mild hyperglycemia.'),('HNF1A-MODY as the best renal-cyst phenotype','Renal developmental abnormalities particularly suggest HNF1B.'),('KCNJ11 neonatal diabetes as the characteristic adult renal-cyst syndrome','Its usual phenotype is different.')],
 'Extrapancreatic findings can identify a molecular syndrome', '**HNF1B disease can combine diabetes with renal developmental abnormalities.**',['Hypomagnesemia and pancreatic abnormalities may occur.','A family history may be absent because de novo variants occur.'], '**Assess the whole syndrome.**',['Renal surveillance and genetic counseling matter.','Do not assume the same drug response as HNF1A-MODY.'],[['Gene','HNF1B'],['Kidney','Cysts/developmental disease'],['Additional clue','Hypomagnesemia']],[DX,MO],'clinical_scenario')
q('Diabetes and sensorineural deafness cluster through the maternal family line. Which mechanism is most likely?', 'Mitochondrial diabetes',[
 ('Autosomal dominant GCK disease as the characteristic deafness pattern','Maternal inheritance and hearing loss suggest a mitochondrial cause.'),('Pure acquired steroid diabetes','This does not explain the inheritance pattern.'),('A Y-linked form of diabetes','Maternal transmission contradicts a Y-linked mechanism.')],
 'Inheritance direction can be diagnostically informative', '**Maternally inherited diabetes and deafness is associated with mitochondrial DNA variants.**',['Clinical severity and organ involvement vary.','A molecular diagnosis can change surveillance and family counseling.'], '**Evaluate associated systems and treatment suitability.**',['Do not infer all family members have identical expression.','Specialist assessment guides therapy in mitochondrial disease.'],[['Inheritance','Maternal'],['Clue','Sensorineural deafness'],['Mechanism','Mitochondrial dysfunction']],[DX,MO],'clinical_scenario')
q('Chronic calcific pancreatitis, pancreatic exocrine insufficiency and new diabetes occur together. Which classification is most appropriate?', 'Diabetes due to exocrine pancreatic disease',[
 ('Autoimmune type 1 diabetes is established by insulin need alone','Pancreatic destruction can also cause insulin deficiency.'),('Ordinary type 2 diabetes is proven by adult onset','The pancreatic disease provides a specific alternative mechanism.'),('GCK-MODY is the expected consequence of pancreatitis','A glucokinase variant is unrelated to acquired pancreatic destruction.')],
 'Pancreatic disease can damage more than insulin secretion', '**Loss of beta cells and counterregulatory glucagon can produce labile glycemia.**',['Exocrine insufficiency affects nutrition and absorption.','Type 2 risk factors can coexist.'], '**Treat nutrition and pancreatic disease alongside glycemia.**',['Pancreatic enzyme replacement may be needed.','Assess hypoglycemia risk when choosing and titrating insulin.'],[['Cause','Exocrine pancreatic disease'],['Endocrine deficit','Insulin and sometimes glucagon'],['Management','Glycemia plus nutrition/exocrine care']],[DX],'clinical_scenario')
